-- 2026-11-22: 장소 제보 서버 검증용 코스별 범위(경계 상자). 화면의 '코스에서 80m' 검사를 우회해도 코스에서 약 500m 넘게 떨어진 좌표는 서버가 거절한다.
create table if not exists public.route_bbox (route_id text primary key, min_lat double precision not null, max_lat double precision not null, min_lon double precision not null, max_lon double precision not null);
alter table public.route_bbox enable row level security;
revoke all on table public.route_bbox from anon, authenticated;
on conflict (route_id) do update set min_lat=excluded.min_lat,max_lat=excluded.max_lat,min_lon=excluded.min_lon,max_lon=excluded.max_lon;

-- submit_poi_user: 범위 검사 추가(코스 경계 상자 ± 0.005도, 약 500m). 범위가 없는 코스는 건너뛴다. 나머지는 participation_v6.sql 과 같다.
do $$
declare src text;
begin
  select pg_get_functiondef('public.submit_poi_user(text,text,double precision,double precision,int,text)'::regprocedure) into src;
  if src not like '%route_bbox%' then
    src := replace(src, E'  if p_acc < 0 or p_acc > 30 then return ''accuracy''; end if;',
      E'  if p_acc < 0 or p_acc > 30 then return ''accuracy''; end if;\n  if exists (select 1 from public.route_bbox b where b.route_id = p_route and (p_lat < b.min_lat - 0.005 or p_lat > b.max_lat + 0.005 or p_lon < b.min_lon - 0.005 or p_lon > b.max_lon + 0.005)) then return ''region''; end if;');
    execute src;
  end if;
end $$;
